import { useEffect, useState } from "react";
import axios from "axios";
import Accordion from "react-bootstrap/Accordion";

function EmployeeList({ departmentId }) {
  const [employees, setEmployees] = useState([]);
  const [workons, setWorkons] = useState([]);
  const [projects, setProjects] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      const empRes = await axios.get("http://localhost:9999/employees");
      setEmployees(empRes.data);

      const workRes = await axios.get("http://localhost:9999/workons");
      setWorkons(workRes.data);

      const proRes = await axios.get("http://localhost:9999/projects");
      setProjects(proRes.data);
    };
    fetchData();
  }, []);

  // Filter employees by department
  const filteredEmployees = employees.filter(
    (emp) => String(emp.depId) === String(departmentId)
  );

  // Get project name by proId
  const getProjectName = (proId) => {
    const project = projects.find((p) => String(p.id) === String(proId));
    return project ? project.proName : "";
  };

  // Get work records for a specific employee
  const getWorkons = (empId) => {
    return workons.filter((w) => String(w.empId) === String(empId));
  };

  // Calculate salary: hourly = empSalary/176, salary = hourly * workHours
  const calcSalary = (empSalary, workHours) => {
    const hourly = empSalary / 176;
    return hourly * workHours;
  };

  // Calculate total salary across all projects for an employee
  const calcTotalSalary = (emp) => {
    const works = getWorkons(emp.id);
    return works.reduce(
      (total, w) => total + calcSalary(emp.empSalary, w.workHours),
      0
    );
  };

  // Format number as VND
  const formatVND = (amount) => {
    return Math.round(amount).toLocaleString("vi-VN");
  };

  return (
    <div>
      <h3>Employee List</h3>
      <Accordion>
        {filteredEmployees.map((emp, index) => {
          const fullName = `${emp.empName.firstName} ${emp.empName.lastName}`;
          const isManager = emp.supervisorId === null;
          const works = getWorkons(emp.id);
          const totalSalary = calcTotalSalary(emp);

          return (
            <Accordion.Item eventKey={String(index)} key={emp.id}>
              <Accordion.Header>
                #{emp.id} - {fullName}
                {isManager && (
                  <span
                    style={{
                      marginLeft: "10px",
                      backgroundColor: "#0d6efd",
                      color: "white",
                      padding: "2px 8px",
                      borderRadius: "4px",
                      fontSize: "12px",
                    }}
                  >
                    Manager
                  </span>
                )}
              </Accordion.Header>
              <Accordion.Body>
                {/* Basic Employee Info */}
                <ul>
                  <li>
                    <strong>EmployeeId:</strong> {emp.id}
                  </li>
                  <li>
                    <strong>Fullname:</strong> {fullName}
                  </li>
                  <li>
                    <strong>Gender:</strong> {emp.empGender}
                  </li>
                  <li>
                    <strong>Birthdate:</strong> {emp.empBirthdate}
                  </li>
                </ul>

                {/* Project Work Table */}
                {works.length > 0 && (
                  <>
                    <p>
                      <strong>Work on projects</strong>
                    </p>
                    <table
                      border="1"
                      style={{ width: "100%", borderCollapse: "collapse" }}
                    >
                      <thead style={{ backgroundColor: "#f0f0f0" }}>
                        <tr>
                          <th style={{ padding: "6px 10px" }}>WorkId</th>
                          <th style={{ padding: "6px 10px" }}>Project name</th>
                          <th style={{ padding: "6px 10px" }}>Work hours</th>
                          <th style={{ padding: "6px 10px" }}>Salary (VND)</th>
                        </tr>
                      </thead>
                      <tbody>
                        {works.map((w) => (
                          <tr key={w.id}>
                            <td style={{ padding: "6px 10px" }}>{w.id}</td>
                            <td style={{ padding: "6px 10px" }}>
                              {getProjectName(w.proId)}
                            </td>
                            <td style={{ padding: "6px 10px" }}>
                              {w.workHours}
                            </td>
                            <td style={{ padding: "6px 10px" }}>
                              {formatVND(calcSalary(emp.empSalary, w.workHours))}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>

                    {/* Total Salary */}
                    <div
                      style={{
                        marginTop: "8px",
                        backgroundColor: "#0d6efd",
                        color: "white",
                        padding: "6px 12px",
                        borderRadius: "4px",
                        display: "inline-block",
                      }}
                    >
                      Projects Salary: {formatVND(totalSalary)} VND
                    </div>
                  </>
                )}
              </Accordion.Body>
            </Accordion.Item>
          );
        })}
      </Accordion>
    </div>
  );
}

export default EmployeeList;
